// Helper function to convert ConfigValue to Python types
ConfigValue configValueToPython(ConfigValue val) {
    return val;
}

// Helper function to convert Python types to ConfigValue
ConfigValue pythonToConfigValue(py::object obj) {
    if (py::isinstance<py::int_>(obj)) {
        return obj.cast<int>();
    } else if (py::isinstance<py::int64_t>(obj)) {
        return obj.cast<int64_t>();
    } else if (py::isinstance<py::float_>(obj)) {
        return obj.cast<double>();
    } else if (py::isinstance<py::bool_>(obj)) {
        return obj.cast<bool>();
    } else if (py::isinstance<py::str>(obj)) {
        return obj.cast<std::string>();
    } else if (py::isinstance<py::list>(obj)) {
        py::list list = obj.cast<py::list>();
        if (!list.empty()) {
            if (py::isinstance<py::int_>(list[0])) {
                std::vector<int> vec;
                vec.reserve(list.size());
                for (auto item : list) {
                    vec.push_back(item.cast<int>());
                }
                return vec;
            } else if (py::isinstance<py::float_>(list[0])) {
                std::vector<double> vec;
                vec.reserve(list.size());
                for (auto item : list) {
                    vec.push_back(item.cast<double>());
                }
                return vec;
            } else if (py::isinstance<py::str>(list[0])) {
                std::vector<std::string> vec;
                vec.reserve(list.size());
                for (auto item : list) {
                    vec.push_back(item.cast<std::string>());
                }
                return vec;
            }
        }
    }
    throw py::type_error("Unsupported Python type for ConfigValue");
}

